+    mockGet.mockResolvedValueOnce({ data: row('succeeded', { id: 'inv-9' }) });
+    const result = await runLlmFeature(() => suggestChecks('s1'), { pollMs: 1 });
+    expect(result.id).toBe('inv-9');
+    expect(mockGet).toHaveBeenCalledWith('/llm/invocations/inv-9');
+  });
+});
